//! Minimal, dependency-free writer for uncompressed Adobe Photoshop PSD files.
//!
//! Supports 8-bit and 16-bit RGB/RGBA images (3 or 4 channels) with zero or
//! more layers. Pixel data is supplied in planar form (all red samples, then
//! all green samples, and so on) and is written with Run-Length-free
//! compression (compression marker 0) in Photoshop's big-endian byte order.
//!
//! The unit tests in this module parse the generated bytes back with a small
//! independent reader. This is **static self-parse verification only, not
//! Photoshop-open verification**; no Adobe application was involved.

use anyhow::{Context, Result, bail, ensure};

/// Sample depth of a PSD document.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PsdSampleDepth {
    Eight,
    Sixteen,
}

impl PsdSampleDepth {
    fn bytes_per_sample(self) -> usize {
        match self {
            Self::Eight => 1,
            Self::Sixteen => 2,
        }
    }

    fn header_value(self) -> u16 {
        match self {
            Self::Eight => 8,
            Self::Sixteen => 16,
        }
    }
}

/// Planar pixel samples for one image or one layer.
///
/// `U8` is used with [`PsdSampleDepth::Eight`] and `U16` with
/// [`PsdSampleDepth::Sixteen`]. The slice holds `channels * width * height`
/// samples: R plane, G plane, B plane, then (if present) the alpha plane.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PsdPixels<'a> {
    U8(&'a [u8]),
    U16(&'a [u16]),
}

/// One layer record plus its planar channel samples.
#[derive(Debug, Clone, Copy)]
pub struct PsdLayer<'a> {
    pub name: &'a str,
    pub top: i32,
    pub left: i32,
    pub bottom: i32,
    pub right: i32,
    /// 0..=255; Photoshop treats this as an opacity percentage (255 = 100%).
    pub opacity: u8,
    pub visible: bool,
    /// Photoshop blend mode signature key, e.g. `*b"norm"` or `*b"scrn"`.
    pub blend_mode_key: [u8; 4],
    /// Planar samples for this layer; channel count is inferred as 3 or 4 from
    /// the slice length and the layer rectangle.
    pub channels: PsdPixels<'a>,
}

/// A complete PSD document description.
#[derive(Debug, Clone, Copy)]
pub struct PsdImage<'a> {
    pub width: u32,
    pub height: u32,
    pub depth: PsdSampleDepth,
    /// Merged (composite) image data. Its length determines whether the file
    /// is RGB (3 channels) or RGBA (4 channels).
    pub merged: PsdPixels<'a>,
    pub layers: &'a [PsdLayer<'a>],
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

fn push_u16(out: &mut Vec<u8>, value: u16) {
    out.extend_from_slice(&value.to_be_bytes());
}

fn push_i16(out: &mut Vec<u8>, value: i16) {
    out.extend_from_slice(&value.to_be_bytes());
}

fn push_u32(out: &mut Vec<u8>, value: u32) {
    out.extend_from_slice(&value.to_be_bytes());
}

fn push_i32(out: &mut Vec<u8>, value: i32) {
    out.extend_from_slice(&value.to_be_bytes());
}

#[derive(Debug, Clone, Copy)]
enum PlaneData<'a> {
    Bytes(&'a [u8]),
    Words(&'a [u16]),
}

fn sample_count(pixels: PsdPixels<'_>) -> usize {
    match pixels {
        PsdPixels::U8(bytes) => bytes.len(),
        PsdPixels::U16(words) => words.len(),
    }
}

/// Infer whether the planar data holds 3 or 4 channels.
fn infer_channel_count(pixels: PsdPixels<'_>, plane_samples: usize, label: &str) -> Result<usize> {
    ensure!(plane_samples > 0, "{label}: plane size is zero");
    let total = sample_count(pixels);
    let three = plane_samples
        .checked_mul(3)
        .with_context(|| format!("{label}: channel count overflow"))?;
    let four = plane_samples
        .checked_mul(4)
        .with_context(|| format!("{label}: channel count overflow"))?;
    if total == three {
        Ok(3)
    } else if total == four {
        Ok(4)
    } else {
        bail!(
            "{label}: expected {} (RGB) or {} (RGBA) samples, got {}",
            three,
            four,
            total
        )
    }
}

/// Check that the sample container matches the requested depth and length.
fn validate_pixels<'a>(
    pixels: PsdPixels<'a>,
    depth: PsdSampleDepth,
    channels: usize,
    plane_samples: usize,
    label: &str,
) -> Result<PlaneData<'a>> {
    let expected = channels
        .checked_mul(plane_samples)
        .with_context(|| format!("{label}: sample count overflow"))?;
    match (depth, pixels) {
        (PsdSampleDepth::Eight, PsdPixels::U8(bytes)) => {
            ensure!(
                bytes.len() == expected,
                "{label}: expected {expected} bytes, got {}",
                bytes.len()
            );
            Ok(PlaneData::Bytes(bytes))
        }
        (PsdSampleDepth::Sixteen, PsdPixels::U16(words)) => {
            ensure!(
                words.len() == expected,
                "{label}: expected {expected} u16 samples, got {}",
                words.len()
            );
            Ok(PlaneData::Words(words))
        }
        (PsdSampleDepth::Eight, PsdPixels::U16(_)) => {
            bail!("{label}: 8-bit PSD requires PsdPixels::U8")
        }
        (PsdSampleDepth::Sixteen, PsdPixels::U8(_)) => {
            bail!("{label}: 16-bit PSD requires PsdPixels::U16")
        }
    }
}

/// Append one plane in Photoshop byte order (16-bit values become big-endian).
fn append_plane(
    out: &mut Vec<u8>,
    data: PlaneData<'_>,
    channel: usize,
    plane_samples: usize,
) -> Result<()> {
    let start = channel
        .checked_mul(plane_samples)
        .context("plane offset overflow")?;
    let end = start
        .checked_add(plane_samples)
        .context("plane range overflow")?;
    match data {
        PlaneData::Bytes(bytes) => {
            let plane = bytes.get(start..end).context("plane slice out of range")?;
            out.extend_from_slice(plane);
        }
        PlaneData::Words(words) => {
            let plane = words.get(start..end).context("plane slice out of range")?;
            let needed = plane
                .len()
                .checked_mul(2)
                .context("plane byte count overflow")?;
            out.reserve(needed);
            for &sample in plane {
                out.extend_from_slice(&sample.to_be_bytes());
            }
        }
    }
    Ok(())
}

fn validate_rect(layer: &PsdLayer<'_>, width: u32, height: u32, label: &str) -> Result<()> {
    let left = i64::from(layer.left);
    let top = i64::from(layer.top);
    let right = i64::from(layer.right);
    let bottom = i64::from(layer.bottom);
    ensure!(left >= 0 && top >= 0, "{label}: layer origin must be non-negative");
    ensure!(right > left && bottom > top, "{label}: layer rect must be non-empty");
    ensure!(
        right <= i64::from(width) && bottom <= i64::from(height),
        "{label}: layer rect exceeds the canvas"
    );
    Ok(())
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/// Encode a PSD document with no compression and no additional layer info.
///
/// Returns an error (never panics) for depth/container mismatches, wrong
/// planar lengths, out-of-bounds layer rectangles, overlong layer names or
/// arithmetic overflow.
pub fn encode_psd(image: &PsdImage<'_>) -> Result<Vec<u8>> {
    encode_psd_with_icc(image, None)
}

/// Like [`encode_psd`], additionally embedding `icc` as image resource 1039
/// (ICC profile) when given.
pub fn encode_psd_with_icc(image: &PsdImage<'_>, icc: Option<&[u8]>) -> Result<Vec<u8>> {
    let width = usize::try_from(image.width).context("PSD width does not fit usize")?;
    let height = usize::try_from(image.height).context("PSD height does not fit usize")?;
    ensure!(width > 0 && height > 0, "PSD canvas must be non-empty");
    let plane_samples = width
        .checked_mul(height)
        .context("PSD canvas area overflow")?;

    let merged_channels = infer_channel_count(image.merged, plane_samples, "merged image")?;
    let merged_data = validate_pixels(
        image.merged,
        image.depth,
        merged_channels,
        plane_samples,
        "merged image",
    )?;
    ensure!(
        image.layers.len() <= i16::MAX as usize,
        "too many layers for a PSD layer count"
    );

    // Layer records and channel image data are separate blocks inside the
    // layer info section, so build them independently.
    let mut records = Vec::new();
    let mut channel_data = Vec::new();

    for (index, layer) in image.layers.iter().enumerate() {
        let label = format!("layer {index} ('{}')", layer.name);
        validate_rect(layer, image.width, image.height, &label)?;

        let layer_width = usize::try_from(layer.right - layer.left)
            .context("layer width does not fit usize")?;
        let layer_height = usize::try_from(layer.bottom - layer.top)
            .context("layer height does not fit usize")?;
        let layer_plane_samples = layer_width
            .checked_mul(layer_height)
            .context("layer area overflow")?;
        let layer_channels = infer_channel_count(layer.channels, layer_plane_samples, &label)?;
        let layer_data = validate_pixels(
            layer.channels,
            image.depth,
            layer_channels,
            layer_plane_samples,
            &label,
        )?;
        let name_bytes = layer.name.as_bytes();
        ensure!(
            name_bytes.len() <= 255,
            "{label}: Pascal layer name exceeds 255 bytes"
        );

        // Channel image data: 2-byte compression marker + raw plane samples.
        let mut channel_lengths = Vec::with_capacity(layer_channels);
        for channel in 0..layer_channels {
            let mut encoded = Vec::with_capacity(
                2 + layer_plane_samples * image.depth.bytes_per_sample(),
            );
            push_u16(&mut encoded, 0); // compression = Raw
            append_plane(&mut encoded, layer_data, channel, layer_plane_samples)?;
            let encoded_len = u32::try_from(encoded.len()).context("channel data exceeds u32")?;
            channel_lengths.push(encoded_len);
            channel_data.extend_from_slice(&encoded);
        }

        // Layer record.
        push_i32(&mut records, layer.top);
        push_i32(&mut records, layer.left);
        push_i32(&mut records, layer.bottom);
        push_i32(&mut records, layer.right);
        push_u16(&mut records, u16::try_from(layer_channels)?);
        for (channel, length) in channel_lengths.iter().enumerate() {
            // Photoshop uses -1 (0xFFFF) for a layer's transparency channel.
            let channel_id = if channel == 3 {
                -1i16
            } else {
                i16::try_from(channel)?
            };
            push_i16(&mut records, channel_id);
            push_u32(&mut records, *length);
        }
        records.extend_from_slice(b"8BIM");
        records.extend_from_slice(&layer.blend_mode_key);
        records.push(layer.opacity);
        records.push(0); // clipping
        records.push(if layer.visible { 0x02 | 0x08 } else { 0x08 });
        records.push(0); // filler

        // Extra data: no mask, no blending ranges, Pascal name padded to even.
        let mut extra = Vec::with_capacity(10 + name_bytes.len() + 1);
        push_u32(&mut extra, 0); // global mask length
        push_u32(&mut extra, 0); // blending ranges length
        extra.push(u8::try_from(name_bytes.len())?);
        extra.extend_from_slice(name_bytes);
        if name_bytes.len() % 2 == 0 {
            extra.push(0); // 1 length byte + even name length -> pad to even
        }
        push_u32(&mut records, u32::try_from(extra.len()).context("extra data exceeds u32")?);
        records.extend_from_slice(&extra);
    }

    let mut layer_info = Vec::new();
    push_i16(&mut layer_info, i16::try_from(image.layers.len())?);
    layer_info.extend_from_slice(&records);
    layer_info.extend_from_slice(&channel_data);
    let layer_info_len = u32::try_from(layer_info.len()).context("layer info exceeds u32")?;

    // Outer layer/mask length covers the layer-info length field, the layer
    // info itself and the 4-byte global layer mask info length.
    let layer_mask_len = u32::try_from(
        layer_info
            .len()
            .checked_add(8)
            .context("layer/mask section overflow")?,
    )
    .context("layer/mask section exceeds u32")?;

    let mut out = Vec::new();
    out.extend_from_slice(b"8BPS");
    push_u16(&mut out, 1); // version
    out.extend_from_slice(&[0u8; 6]); // reserved
    push_u16(&mut out, u16::try_from(merged_channels)?);
    push_u32(&mut out, image.height);
    push_u32(&mut out, image.width);
    push_u16(&mut out, image.depth.header_value());
    push_u16(&mut out, 3); // color mode = RGB

    push_u32(&mut out, 0); // color mode data length
    match icc.filter(|icc| !icc.is_empty()) {
        Some(icc) => {
            // Image resource block: "8BIM", id, empty Pascal name (padded
            // to even), u32 length, data padded to even.
            let mut res = Vec::with_capacity(icc.len() + 16);
            res.extend_from_slice(b"8BIM");
            push_u16(&mut res, 1039);
            res.extend_from_slice(&[0, 0]);
            push_u32(&mut res, u32::try_from(icc.len()).context("ICC profile exceeds u32")?);
            res.extend_from_slice(icc);
            if icc.len() % 2 == 1 {
                res.push(0);
            }
            push_u32(&mut out, u32::try_from(res.len()).context("image resources exceed u32")?);
            out.extend_from_slice(&res);
        }
        None => push_u32(&mut out, 0), // image resources length
    }

    push_u32(&mut out, layer_mask_len);
    push_u32(&mut out, layer_info_len);
    out.extend_from_slice(&layer_info);
    push_u32(&mut out, 0); // global layer mask info length

    push_u16(&mut out, 0); // merged image compression = Raw
    for channel in 0..merged_channels {
        append_plane(&mut out, merged_data, channel, plane_samples)?;
    }

    Ok(out)
}

// ---------------------------------------------------------------------------
// Tests: independent big-endian re-reader (static self-parse verification)
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    struct Reader<'a> {
        bytes: &'a [u8],
        pos: usize,
    }

    impl<'a> Reader<'a> {
        fn new(bytes: &'a [u8]) -> Self {
            Self { bytes, pos: 0 }
        }

        fn take(&mut self, count: usize) -> &'a [u8] {
            let end = self.pos.checked_add(count).expect("reader offset overflow");
            let slice = &self.bytes[self.pos..end];
            self.pos = end;
            slice
        }

        fn u8(&mut self) -> u8 {
            self.take(1)[0]
        }

        fn u16(&mut self) -> u16 {
            u16::from_be_bytes(self.take(2).try_into().unwrap())
        }

        fn i16(&mut self) -> i16 {
            i16::from_be_bytes(self.take(2).try_into().unwrap())
        }

        fn u32(&mut self) -> u32 {
            u32::from_be_bytes(self.take(4).try_into().unwrap())
        }

        fn i32(&mut self) -> i32 {
            i32::from_be_bytes(self.take(4).try_into().unwrap())
        }
    }

    fn u8_planes(width: usize, height: usize, seed: u8, channels: usize) -> Vec<u8> {
        let mut data = Vec::with_capacity(channels * width * height);
        for channel in 0..channels {
            for pixel in 0..width * height {
                let value = seed
                    ^ (channel as u8).wrapping_mul(37)
                    ^ (pixel as u8).wrapping_mul(11);
                data.push(value);
            }
        }
        data
    }

    fn expected_plane_bytes(
        pixels: PsdPixels<'_>,
        channel: usize,
        plane_samples: usize,
    ) -> Vec<u8> {
        let start = channel * plane_samples;
        let end = start + plane_samples;
        match pixels {
            PsdPixels::U8(bytes) => bytes[start..end].to_vec(),
            PsdPixels::U16(words) => {
                let mut out = Vec::with_capacity(plane_samples * 2);
                for &value in &words[start..end] {
                    out.extend_from_slice(&value.to_be_bytes());
                }
                out
            }
        }
    }

    fn plane_count(pixels: PsdPixels<'_>, plane_samples: usize) -> usize {
        match pixels {
            PsdPixels::U8(bytes) => bytes.len() / plane_samples,
            PsdPixels::U16(words) => words.len() / plane_samples,
        }
    }

    /// Re-read the entire file with an independent BE parser and compare every
    /// payload byte with the source data.
    fn verify_psd(image: &PsdImage<'_>, bytes: &[u8]) {
        let mut r = Reader::new(bytes);
        let bytes_per_sample = image.depth.bytes_per_sample();

        // File header.
        assert_eq!(r.take(4), b"8BPS");
        assert_eq!(r.u16(), 1);
        assert_eq!(r.take(6), &[0u8; 6]);
        let merged_planes = (image.width as usize) * (image.height as usize);
        let merged_channels = plane_count(image.merged, merged_planes);
        assert_eq!(r.u16() as usize, merged_channels);
        assert_eq!(r.u32(), image.height);
        assert_eq!(r.u32(), image.width);
        assert_eq!(r.u16(), image.depth.header_value());
        assert_eq!(r.u16(), 3);

        let color_mode_len = r.u32() as usize;
        assert_eq!(color_mode_len, 0);
        r.take(color_mode_len);
        let resources_len = r.u32() as usize;
        assert_eq!(resources_len, 0);
        r.take(resources_len);

        // Layer and mask information.
        let mask_len = r.u32() as usize;
        let mask_end = r.pos + mask_len;
        assert!(mask_end <= bytes.len());
        let layer_info_len = r.u32() as usize;
        let layer_info_end = r.pos + layer_info_len;
        assert!(layer_info_end <= mask_end);
        let layer_count = r.i16();
        assert!(layer_count >= 0);
        assert_eq!(layer_count as usize, image.layers.len());

        struct ParsedChannel {
            id: i16,
            data_len: usize,
        }
        let mut parsed_layers = Vec::new();

        for layer in image.layers {
            assert_eq!(r.i32(), layer.top, "top of '{}'", layer.name);
            assert_eq!(r.i32(), layer.left, "left of '{}'", layer.name);
            assert_eq!(r.i32(), layer.bottom, "bottom of '{}'", layer.name);
            assert_eq!(r.i32(), layer.right, "right of '{}'", layer.name);

            let layer_planes = ((layer.right - layer.left) * (layer.bottom - layer.top)) as usize;
            let channel_count = r.u16() as usize;
            assert_eq!(channel_count, plane_count(layer.channels, layer_planes));

            let mut channels = Vec::with_capacity(channel_count);
            for index in 0..channel_count {
                let id = r.i16();
                let data_len = r.u32() as usize;
                let expected_id = if index == 3 { -1i16 } else { index as i16 };
                assert_eq!(id, expected_id, "channel id of '{}'", layer.name);
                assert_eq!(
                    data_len,
                    2 + layer_planes * bytes_per_sample,
                    "channel data length of '{}'",
                    layer.name
                );
                channels.push(ParsedChannel { id, data_len });
            }

            assert_eq!(r.take(4), b"8BIM", "blend signature of '{}'", layer.name);
            assert_eq!(
                r.take(4),
                layer.blend_mode_key.as_slice(),
                "blend mode of '{}'",
                layer.name
            );
            assert_eq!(r.u8(), layer.opacity, "opacity of '{}'", layer.name);
            assert_eq!(r.u8(), 0, "clipping of '{}'", layer.name);
            let expected_flags = if layer.visible { 0x02 | 0x08 } else { 0x08 };
            assert_eq!(r.u8(), expected_flags, "flags of '{}'", layer.name);
            assert_eq!(r.u8(), 0, "filler of '{}'", layer.name);

            let extra_len = r.u32() as usize;
            let extra_start = r.pos;
            assert_eq!(r.u32(), 0, "global mask length of '{}'", layer.name);
            assert_eq!(r.u32(), 0, "blending ranges length of '{}'", layer.name);
            let name_len = r.u8() as usize;
            assert_eq!(r.take(name_len), layer.name.as_bytes());
            // Pascal string: length byte + name, padded to an even byte count.
            if name_len % 2 == 0 {
                assert_eq!(r.u8(), 0, "Pascal name pad byte of '{}'", layer.name);
            }
            assert!((r.pos - extra_start) % 2 == 0, "extra data not even");
            r.take(extra_len - (r.pos - extra_start));

            parsed_layers.push((layer, channels));
        }

        for (layer, channels) in parsed_layers {
            let layer_planes = ((layer.right - layer.left) * (layer.bottom - layer.top)) as usize;
            for (index, channel) in channels.iter().enumerate() {
                assert_eq!(channel.id, if index == 3 { -1 } else { index as i16 });
                assert_eq!(r.u16(), 0, "compression of '{}' channel {index}", layer.name);
                let payload = r.take(channel.data_len - 2);
                assert_eq!(
                    payload,
                    expected_plane_bytes(layer.channels, index, layer_planes),
                    "layer '{}' channel {index} plane mismatch",
                    layer.name
                );
            }
        }
        assert_eq!(r.pos, layer_info_end, "channel image data length mismatch");
        assert_eq!(r.u32(), 0, "global layer mask info");
        assert_eq!(r.pos, mask_end, "layer/mask section length mismatch");

        // Merged image data.
        assert_eq!(r.u16(), 0, "merged compression");
        for index in 0..merged_channels {
            let payload = r.take(merged_planes * bytes_per_sample);
            assert_eq!(
                payload,
                expected_plane_bytes(image.merged, index, merged_planes),
                "merged channel {index} plane mismatch"
            );
        }
        assert_eq!(r.pos, bytes.len(), "trailing bytes after merged image");
    }

    #[test]
    fn icc_profile_is_written_as_image_resource_1039() {
        let merged = u8_planes(2, 2, 3, 3);
        let image = PsdImage { width: 2, height: 2, depth: PsdSampleDepth::Eight, merged: PsdPixels::U8(&merged), layers: &[] };
        let icc = [7u8; 5];
        let bytes = encode_psd_with_icc(&image, Some(&icc)).unwrap();
        assert_eq!(&bytes[0..4], b"8BPS");
        let mut r = Reader::new(&bytes);
        r.take(26);
        assert_eq!(r.u32(), 0);
        let res_len = r.u32();
        assert_eq!(res_len, 4 + 2 + 2 + 4 + 6);
        assert_eq!(r.take(4), b"8BIM");
        assert_eq!(r.u16(), 1039);
        r.take(2);
        assert_eq!(r.u32(), 5);
        assert_eq!(r.take(5), &icc);
    }

    #[test]
    fn eight_bit_rgba_two_layers() {
        let (width, height) = (3usize, 2usize);
        let base = u8_planes(width, height, 0x10, 4);
        let glow = u8_planes(2, 1, 0xA5, 4);
        let merged = u8_planes(width, height, 0x5A, 4);
        let layers = [
            PsdLayer {
                name: "Base",
                top: 0,
                left: 0,
                bottom: height as i32,
                right: width as i32,
                opacity: 255,
                visible: true,
                blend_mode_key: *b"norm",
                channels: PsdPixels::U8(&base),
            },
            PsdLayer {
                name: "Glow",
                top: 1,
                left: 1,
                bottom: height as i32,
                right: width as i32,
                opacity: 128,
                visible: true,
                blend_mode_key: *b"scrn",
                channels: PsdPixels::U8(&glow),
            },
        ];
        let image = PsdImage {
            width: width as u32,
            height: height as u32,
            depth: PsdSampleDepth::Eight,
            merged: PsdPixels::U8(&merged),
            layers: &layers,
        };
        let bytes = encode_psd(&image).expect("8-bit RGBA encoding must succeed");
        verify_psd(&image, &bytes);
    }

    #[test]
    fn sixteen_bit_rgb_one_layer() {
        let (width, height) = (2usize, 2usize);
        let source = [
            0x1234u16, 0xABCD, 0x0001, 0xFFFF, 0x00FF, 0xFF00, 0x1234, 0x5678, 0x8000, 0x7FFF,
            0xABCD, 0x0000,
        ];
        let merged: Vec<u16> = (0..12u16).map(|i| 0x1000u16.wrapping_mul(i + 1)).collect();
        let layers = [PsdLayer {
            name: "HiBit",
            top: 0,
            left: 0,
            bottom: height as i32,
            right: width as i32,
            opacity: 200,
            visible: true,
            blend_mode_key: *b"norm",
            channels: PsdPixels::U16(&source),
        }];
        let image = PsdImage {
            width: width as u32,
            height: height as u32,
            depth: PsdSampleDepth::Sixteen,
            merged: PsdPixels::U16(&merged),
            layers: &layers,
        };
        let bytes = encode_psd(&image).expect("16-bit RGB encoding must succeed");
        verify_psd(&image, &bytes);
    }

    #[test]
    fn invalid_inputs_return_errors_without_panicking() {
        let bytes8 = [0u8; 12]; // 3 channels * 2x2
        let words16 = [0u16; 12];
        let layer = PsdLayer {
            name: "Bad",
            top: 0,
            left: 0,
            bottom: 2,
            right: 2,
            opacity: 255,
            visible: true,
            blend_mode_key: *b"norm",
            channels: PsdPixels::U8(&bytes8),
        };

        // Wrong pixel container for the declared depth.
        let depth_mismatch = PsdImage {
            width: 2,
            height: 2,
            depth: PsdSampleDepth::Sixteen,
            merged: PsdPixels::U8(&bytes8),
            layers: &[layer],
        };
        assert!(encode_psd(&depth_mismatch).is_err());

        // Wrong merged plane length.
        let short_merged = PsdImage {
            width: 2,
            height: 2,
            depth: PsdSampleDepth::Eight,
            merged: PsdPixels::U8(&bytes8[..11]),
            layers: &[layer],
        };
        assert!(encode_psd(&short_merged).is_err());

        // Layer rectangle outside the canvas.
        let outside = PsdLayer {
            right: 3,
            ..layer
        };
        let outside_rect = PsdImage {
            width: 2,
            height: 2,
            depth: PsdSampleDepth::Eight,
            merged: PsdPixels::U8(&bytes8),
            layers: &[outside],
        };
        assert!(encode_psd(&outside_rect).is_err());

        // Layer name longer than a Pascal string can express.
        let long_name = "L".repeat(256);
        let long_layer = PsdLayer {
            name: &long_name,
            ..layer
        };
        let long_name_image = PsdImage {
            width: 2,
            height: 2,
            depth: PsdSampleDepth::Eight,
            merged: PsdPixels::U8(&bytes8),
            layers: &[long_layer],
        };
        assert!(encode_psd(&long_name_image).is_err());

        // 16-bit happy path with a different container still works.
        let valid16 = PsdImage {
            width: 2,
            height: 2,
            depth: PsdSampleDepth::Sixteen,
            merged: PsdPixels::U16(&words16),
            layers: &[],
        };
        assert!(encode_psd(&valid16).is_ok());
    }
}
